# 1991년 파이썬 0.9.1 튜토리얼에 실린 코드 그대로
옛코드 = """class Set():
    def new(self):
        self.elements = []
        return self

    def remove(self, e):
        for i in range(len(self.elements)):
            if self.elements[i] = e:
                del self.elements[i]
                break
"""

try:
    compile(옛코드, "1991.py", "exec")
    print("오늘 파이썬이 그대로 읽었습니다")
except SyntaxError as e:
    print("멈춘 자리:", e.msg)
    print("멈춘 줄  :", e.text.strip())

# 같은지 비교하는 기호 하나만 오늘 것으로 바꿔 봅니다
새코드 = 옛코드.replace("[i] = e", "[i] == e")

try:
    compile(새코드, "1991.py", "exec")
    print()
    print("= 를 == 로 고치자 통과했습니다")
except SyntaxError as e:
    print("아직 멈춤:", e.msg)
